"""A smoke test: the configuration is valid and compiles. Generated by `aaa mcp init`."""

import asyncio
import os
from pathlib import Path

from aaa.mcp import acompile_spec, load_spec

SECRETS = ['ORDERS_API_TOKEN']  # environment variables the configuration refers to (names only)


def test_the_configuration_compiles():
    for name in SECRETS:
        os.environ.setdefault(name, "test-value-not-a-real-secret")
    core = asyncio.run(acompile_spec(load_spec(Path(__file__).parent.parent / "server.json")))
    assert core.list_tools() or core.hidden or core.list_resources() or core.list_prompts()
